const projectId = $('Receive Project').first().json.project_id;
const project = $('Load Project').first().json;
const design = $('Load Design Option').first().json;
const agentPrompt = $('Load Agent Prompt').first().json;
const executionId = $('Start Execution').first().json.id;

const materials = $('Load Materials').all().map(i => i.json).filter(i => i.id);
const matByCategory = {};
materials.forEach(m => {
  if (!matByCategory[m.category]) matByCategory[m.category] = [];
  const priceInfo = m.unit_price ? m.unit_price + 'eur' : 'sin precio';
  matByCategory[m.category].push('  - ' + m.name + ': ' + (m.quantity_estimated || '?') + ' ' + (m.unit || 'ud') + ' x ' + priceInfo);
});
const materialsText = Object.entries(matByCategory).map(([cat, items]) => cat.toUpperCase() + ':\n' + items.join('\n')).join('\n') || '  (Sin materiales cargados)';

const regTasks = $('Load Regulatory Tasks').all().map(i => i.json).filter(i => i.id);
const regText = regTasks.length > 0
  ? regTasks.map(t => '  - ' + t.title + ': ' + (t.estimated_cost ? t.estimated_cost + 'eur' : 'coste no estimado') + ' (' + (t.task_type || 'tramite') + ')').join('\n')
  : '  - No hay tramites con coste estimado';

const priceRefs = $('Load Price References').all().map(i => i.json).filter(i => i.avg_price);
let priceRefsText = '';
if (priceRefs.length > 0) {
  priceRefsText = '\n\nPRECIOS VERIFICADOS PARTIDAS DE OBRA (fuente: CYPE 2024-2025):\n';
  priceRefs.forEach(p => {
    priceRefsText += '  - ' + p.partida + ' (' + p.unit + '): min ' + (p.min_price || '?') + ' / avg ' + p.avg_price + ' / max ' + (p.max_price || '?') + ' eur\n';
  });
  priceRefsText += 'USA estos precios como base para mano de obra en las partidas correspondientes.';
}

// Patologias detectadas (agent_pathology) — sumar como partidas extra
const pathologies = $('Load Pathology Findings').all().map(i => i.json).filter(p => p.id);
let pathologiesText = '';
if (pathologies.length > 0) {
  pathologiesText = '\n\nPATOLOGIAS DETECTADAS EN INSPECCION PREVIA (sumar como partidas extra al breakdown):\n';
  pathologies.forEach(p => {
    const cost = (p.estimated_intervention_cost_min || p.estimated_intervention_cost_max)
      ? (p.estimated_intervention_cost_min || 0) + '-' + (p.estimated_intervention_cost_max || 0) + 'eur'
      : 'sin estimar';
    pathologiesText += '  - [' + (p.severity || '?').toUpperCase() + '] ' + (p.pathology_type || '?') + (p.location_in_property ? ' (' + p.location_in_property + ')' : '') + ': ' + (p.description || '?') + ' — ' + (p.recommended_action || 'accion no definida') + ' — estimado ' + cost + '\n';
  });
  pathologiesText += 'IMPORTANTE: Incluye una partida "Tratamiento de patologias detectadas" en el breakdown con la suma de las cost_min de las patologias high/critical, y mencionalas en risk_notes.';
}

const memoryCases = $('Load Memory Cases').all().map(i => i.json).filter(i => i.id && i.cost_final);
let calibText = '';
if (memoryCases.length > 0) {
  calibText = '\n\nPROYECTOS SIMILARES DEL ESTUDIO (calibracion):\n';
  memoryCases.forEach(mc => {
    let meta = {};
    try { meta = typeof mc.metadata === 'string' ? JSON.parse(mc.metadata) : (mc.metadata || {}); } catch(e) {}
    const area = meta.area_m2 || project.property_area_m2 || null;
    const cpSqm = area ? Math.round(mc.cost_final / area) : null;
    calibText += '  - ' + (mc.project_type || 'reforma') + (area ? ' ~' + area + 'm2' : '') + ': ' + mc.cost_final + 'eur' + (cpSqm ? ' (' + cpSqm + 'eur/m2)' : '') + '\n';
  });
}

const outputFormat = '{"total_estimated":0,"breakdown":[{"partida":"string","importe":0,"notes":"string"}],"scenarios":{"economico":{"total":0,"notes":"string"},"estandar":{"total":0,"notes":"string"},"premium":{"total":0,"notes":"string"}},"adjustments_if_over":["string"],"assumptions":["string"],"risk_notes":"string"}';

const userPrompt = 'Genera una estimacion de costes detallada para el proyecto de reforma.\n\nPROYECTO:\n- Tipo: ' + (project.project_type || 'reforma') + '\n- Localizacion: ' + (project.location_city || '') + ', ' + (project.location_province || '') + '\n- Superficie: ' + (project.property_area_m2 || '?') + ' m2\n- Presupuesto objetivo: ' + (project.budget_target ? project.budget_target + 'eur' : 'No especificado') + '\n\nOPCION DE DISENO SELECCIONADA:\n' + (design.title ? (design.option_number || '') + ': ' + design.title + '\n' + (design.description || '') : 'Sin detalle') + '\n\nMATERIALES IDENTIFICADOS:\n' + materialsText + '\n\nTRAMITES Y COSTES:\n' + regText + priceRefsText
  + pathologiesText + calibText + '\n\nINSTRUCCIONES:\n- Desglose por PARTIDAS DE OBRA (no por materiales individuales)\n- Partidas estandar: Demoliciones, Albanileria, Pavimentos y revestimientos, Fontaneria, Electricidad, Carpinteria, Pintura, Sanitarios y griferia, Cocina mobiliario e instalacion, Honorarios tecnicos, Tasas y licencias, Gestion residuos, Imprevistos\n- OBLIGATORIO incluir Imprevistos minimo 10% del subtotal\n- USA los precios CYPE como base para mano de obra\n- total_estimated debe ser la SUMA EXACTA de todos los importes del breakdown\n- Genera 3 escenarios: economico (-20-25%), estandar (esta estimacion), premium (+25-35%)\n- adjustments_if_over: recortes concretos con ahorro si supera presupuesto objetivo\n- assumptions: supuestos que podrian cambiar el precio si son incorrectos\n\nResponde EXCLUSIVAMENTE con JSON valido:\n' + outputFormat;

// === STUDIO PROFILE INJECTION (B23) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_priorities=_safeStudio(_studio.priorities)||[],_redLines=_safeStudio(_studio.red_lines)||[];
const _SP_COST_LINES=[];
_SP_COST_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'.');
_SP_COST_LINES.push('PRIORIDADES (orden estricto, aplicalas al desglose presupuestario):');
(_priorities||[]).forEach(p=>_SP_COST_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')+(p.detalle?' - '+p.detalle:'')));
_SP_COST_LINES.push('LINEAS ROJAS:');
(_redLines||[]).forEach(l=>_SP_COST_LINES.push('- '+(l.texto||'')));
_SP_COST_LINES.push('REGLA: Si veas que algo del briefing requiere una solucion que el estudio NUNCA hace, no la incluyas en el breakdown; senalalo en notes.');
const _SP_COST=_SP_COST_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
return [{ json: { agent_name: 'agent_costs',
  project_id: projectId,
  execution_id: executionId,
  budget_target: project.budget_target || null,
  prompt_system: _SP_COST + '\n\n' + ((agentPrompt.content) || 'Eres el Agente de Costes de un estudio de arquitectura tecnica. Generas estimaciones economicas precisas y desglosadas por partidas de obra, usando precios reales del mercado espanol de construccion y los materiales ya seleccionados.'),
  prompt_user: userPrompt,
  model: (agentPrompt.model_recommended || 'claude-sonnet-4-20250514').trim(),
  temperature: agentPrompt.temperature || 0.2
}}];

const llmResponse = $('Call LLM').first().json;
const projectId = $('Receive Project').first().json.project_id;
const executionId = $('Start Execution').first().json.id;
const budgetTarget = $('Prepare Costs Prompt').first().json.budget_target;

let parsed = {};
try {
  const content = llmResponse.content || llmResponse.text || llmResponse.message || JSON.stringify(llmResponse);
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  parsed = { total_estimated: 0, breakdown: [], scenarios: {}, adjustments_if_over: [], assumptions: [], risk_notes: 'Error parsing: ' + e.message };
}

let breakdown = parsed.breakdown || [];

const sumBreakdown = breakdown.reduce((acc, p) => acc + (Number(p.importe) || 0), 0);
const totalLLM = Number(parsed.total_estimated) || 0;
const diffPct = totalLLM > 0 ? Math.abs((sumBreakdown - totalLLM) / totalLLM) * 100 : 0;
if (diffPct > 5 && sumBreakdown > 0) parsed.total_estimated = sumBreakdown;

const hasImprevistos = breakdown.some(p => p.partida && p.partida.toLowerCase().includes('imprevisto'));
if (!hasImprevistos && breakdown.length > 0) {
  const subtotal = breakdown.reduce((acc, p) => acc + (Number(p.importe) || 0), 0);
  const imprevisto = Math.round(subtotal * 0.10);
  breakdown.push({ partida: 'Imprevistos (10%)', importe: imprevisto, notes: 'Reserva estandar anadida automaticamente' });
  parsed.total_estimated = subtotal + imprevisto;
}

const finalTotal = Number(parsed.total_estimated) || 0;
const deviationPct = (budgetTarget && Number(budgetTarget) > 0)
  ? Math.round(((finalTotal - Number(budgetTarget)) / Number(budgetTarget)) * 100 * 100) / 100
  : null;

let deviationStatus = 'unknown';
if (deviationPct !== null) {
  if (deviationPct <= 5) deviationStatus = 'within_budget';
  else if (deviationPct <= 20) deviationStatus = 'slight_over';
  else if (deviationPct <= 40) deviationStatus = 'over_budget';
  else deviationStatus = 'critical_over';
}

const priceRefs = $('Load Price References').all().map(i => i.json).filter(i => i.avg_price);
const breakdownFinal = breakdown.map(item => {
  const itemKey = (item.partida || '').toLowerCase().split(' ')[0];
  const ref = priceRefs.find(p => (p.partida || '').toLowerCase().startsWith(itemKey));
  if (ref && ref.avg_price && item.importe) {
    const ratio = Number(item.importe) / Number(ref.avg_price);
    return { ...item, price_verified: true, price_warning: ratio < 0.2 || ratio > 10 };
  }
  return { ...item, price_verified: false, price_warning: false };
});

return [{ json: {
  project_id: projectId,
  execution_id: executionId,
  budget_target: budgetTarget ? Number(budgetTarget) : null,
  total_estimated: finalTotal,
  deviation_pct: deviationPct,
  deviation_status: deviationStatus,
  breakdown: breakdownFinal,
  adjustments_suggested: parsed.adjustments_if_over || [],
  scenarios: parsed.scenarios || {},
  assumptions: parsed.assumptions || [],
  risk_notes: parsed.risk_notes || ''
}}];
